module.onRender:
// CROWDAQ Widget v2 renderer.
//
// Module renderer options:
//   id:         the id of the widget
//   target:     the target element to render into
//   properties: the widget properties (wsBaseUrl, playerVersion, heartbeatIntervalMs)
//
// This block (a) inlines the self-contained CrowdaqWidgetV2 bundle, then
// (b) boots it against the mount host inside `target`. The bundle reads
// xiboIC.info() itself; we only pass the widget properties through.
//
// NB: no <dataType>, so Xibo passes no `items` array — we never reference it.

(function () {
    'use strict';

    // ---- inlined bundle (global CrowdaqWidgetV2) -------------------------------
    // Replaced at package time (tools/package.mjs) with the tsup build output
    // dist/crowdaq-widget-v2.global.js. Until packaged this marker is inert and
    // boot is skipped (the host stays at the empty stencil).
    /* __CROWDAQ_WIDGET_V2_BUNDLE__ */

    if (typeof CrowdaqWidgetV2 === 'undefined' || typeof CrowdaqWidgetV2.boot !== 'function') {
        // Unpackaged XML (the bundle marker was not substituted). Leave the
        // stencil as-is rather than throwing — the layout still renders.
        return;
    }

    // Resolve the host the stencil rendered + the widget properties.
    //
    // `target` is player-runtime-dependent: the Xibo 4.x Linux player passes a
    // jQuery-wrapped element (no `.querySelector`), the headless twin passes a
    // raw DOM Element, and a selector string is possible too. Normalise all of
    // these to a DOM root before querying for the mount host. Falling back to
    // `document` keeps the layout rendering rather than throwing.
    var SEL = '[data-crowdaq-v2-root]';
    var rootEl = null;
    if (typeof target !== 'undefined' && target) {
        if (typeof target === 'string') {
            rootEl = document.querySelector(target);
        } else if (typeof target.querySelector === 'function') {
            rootEl = target; // raw DOM Element / Document
        } else if (typeof target.find === 'function' && typeof target.get === 'function') {
            rootEl = target.get(0) || null; // jQuery object
        } else if (typeof target.length === 'number' && target[0]) {
            rootEl = target[0]; // array-like (jQuery without .get, NodeList)
        }
    }
    if (!rootEl || typeof rootEl.querySelector !== 'function') {
        rootEl = document;
    }
    // The mount host is the stencil's host div; if the resolved root IS the
    // host (target was the host element itself), use it directly.
    var host = rootEl.querySelector(SEL)
        || ((rootEl.matches && rootEl.matches(SEL)) ? rootEl : null)
        || document.querySelector(SEL)
        || rootEl;
    var props = (typeof properties !== 'undefined' && properties) ? properties : {};

    // Properties may arrive as strings (data-attributes); coerce the number.
    var heartbeat = parseInt(props.heartbeatIntervalMs, 10);

    // data-attribute fallbacks (the player may pass properties only via the
    // stencil's data-* attributes rather than the `properties` object).
    var attr = function (name) { return (host.getAttribute && host.getAttribute(name)) || ''; };

    CrowdaqWidgetV2.boot(host, {
        wsBaseUrl: typeof props.wsBaseUrl === 'string' && props.wsBaseUrl ? props.wsBaseUrl : attr('data-crowdaq-ws-base-url'),
        barId: typeof props.barId === 'string' && props.barId ? props.barId : attr('data-crowdaq-bar-id'),
        displayId: typeof props.displayId === 'string' && props.displayId ? props.displayId : attr('data-crowdaq-display-id'),
        playerVersion: typeof props.playerVersion === 'string' && props.playerVersion ? props.playerVersion : (attr('data-crowdaq-player-version') || 'widget-v2'),
        heartbeatIntervalMs: isNaN(heartbeat) ? 30000 : heartbeat
    }).then(function (rt) {
        // Expose the runtime for a headless probe / DevTools inspection.
        try { host.__crowdaqWidgetV2 = rt; } catch (e) { /* ignore */ }
    }).catch(function (err) {
        try { console.error('[crowdaq-widget-v2] boot failed', err); } catch (e) { /* ignore */ }
    });
})();
